138	func parseInts(s string) ([]int, error) {
139		var out []int
140		for _, part := range strings.Split(s, ",") {
141			part = strings.TrimSpace(part)
142			if part == "" {
143				continue
144			}
145			v, err := strconv.Atoi(part)
146			if err != nil {
147				return nil, fmt.Errorf("%q: %w", part, err)
148			}
149			out = append(out, v)
150		}
151		return out, nil
152	}
